 vocab=[('🧭','expectation','expectativa','ék-spek-TÊI-shon'),('⚠️','risk','risco','RÍSK'),('🎒','supplies','suprimentos','sa-PLÁIZ'),('❄️','wilderness','região selvagem','UÍL-der-nis'),('🤔','reality','realidade','ri-Á-li-ti'),('😕','disappointing','decepcionante','dis-a-POIN-ting')],
 gap=('The trip was ___ be a fresh start.','A viagem era para ser um recomeço.',['supposed to','suppose to','supposed for'],'Be supposed to expressa o que era esperado ou combinado.'),
